def is_sorted(lst):
    def has_duplicate(lst):
        seen = set()
        for num in lst:
            if num in seen:
                return True
            seen.add(num)
        return False

    if has_duplicate(lst):
        return False

    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False

    return True

